cssText:
.stage { background: radial-gradient(120vmax 80vmax at 50% 30%, var(--bg-hi) 0%, var(--bg) 62%); }
.hud-series, .hud-badge, .hud-scale, .hud-counter .u, .hud-end .n { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: .14em; font-weight: 500; }
.hud-scale, .hud-counter .u { text-transform: none; letter-spacing: .08em; }   /* units: µ must not upper-case to M */
.hud-series { color: var(--text-2); }
.hud-h, .hud-end .t { font-weight: 800; }
.hud-counter .v, .hud-scale, .hud-badge { font-feature-settings: "tnum" 1; }
.hud-title::before { content: ""; position: absolute; z-index: -1; left: -30vmin; right: -22vmin; top: -26vmin; bottom: -16vmin; background: radial-gradient(closest-side, rgba(3,12,14,.80) 0%, rgba(3,12,14,.66) 55%, rgba(3,12,14,0) 100%); }
.hud-label { border-width: .15vmin; }
.hud-label.mk-dot .mk { box-shadow: 0 0 0 .32vmin var(--hud-ring); }
.hud-badge { text-transform: none; letter-spacing: .02em; }   /* sentence case: long notes fit the corner */
